import{_ as t,o as s,c as a,a0 as r}from"./chunks/framework.CR-yHhk1.js";const v=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),o={name:"explanation/architecture.md"};function i(d,e,n,c,p,l){return s(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Sepia is the <em>mechanism</em> layer for coding-agent sessions. Everything you can do <strong>to</strong> a session or an agent — list stores, attach, prompt, cancel, resolve permissions, restore, rewind, manage agent configs — is sepia&#39;s job. It has no opinion about <em>who</em> should do those things, <em>when</em>, or <em>from where</em>: that policy lives in <a href="https://9aia.com/peregrin/" target="_blank" rel="noreferrer">peregrin</a>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>orchestrator (peregrin, scripts, CI)</span></span>
<span class="line"><span>        │  spawn + ndjson JSON-RPC</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   sepia serve ────────── ControlPlane (sepia-session)</span></span>
<span class="line"><span>        │                       │ attach / prompt / restore</span></span>
<span class="line"><span>        │  spawn + ndjson       ▼</span></span>
<span class="line"><span>        └────────────►  sepia-driver-* binaries</span></span>
<span class="line"><span>                                │ per-agent adapters</span></span>
<span class="line"><span>                                ▼</span></span>
<span class="line"><span>                     devin / cline / claude / cursor stores</span></span></code></pre></div><h2 id="why-mechanism-vs-policy" tabindex="-1">Why mechanism vs policy <a class="header-anchor" href="#why-mechanism-vs-policy" aria-label="Permalink to &quot;Why mechanism vs policy&quot;">​</a></h2><p>Two failure modes drove the split. Policy code (arbitration, routing, queues) wants to evolve fast and is mostly pure logic. Session mechanism wants to be boring — a stable IR, tolerant parsers, careful handling of agent stores you did not design. Gluing them together made both worse; the <code>sepia serve</code> boundary keeps them apart: peregrin links none of sepia&#39;s internals, it spawns the service and speaks the same JSON-RPC framing drivers do.</p><h2 id="the-canonical-ir" tabindex="-1">The canonical IR <a class="header-anchor" href="#the-canonical-ir" aria-label="Permalink to &quot;The canonical IR&quot;">​</a></h2><p>Every agent store — Devin&#39;s SQLite, Cline&#39;s directory layout, Claude&#39;s JSONL transcripts, Cursor&#39;s workspace storage — maps onto one session IR: nodes, messages, tool calls, checkpoints, metadata. Lossy edges are marked <code>lossy</code> in metadata rather than silently dropped, so importers and auditors can see what a store could not express. <a href="./../reference/session-formats.html">Session formats</a> documents the shape.</p><h2 id="drivers-are-binaries-not-libraries" tabindex="-1">Drivers are binaries, not libraries <a class="header-anchor" href="#drivers-are-binaries-not-libraries" aria-label="Permalink to &quot;Drivers are binaries, not libraries&quot;">​</a></h2><p>Store adapters ship as <code>sepia-driver-&lt;id&gt;</code> executables speaking ndjson JSON-RPC over stdio. Discovery order: <code>$SEPIA_DRIVER_DIR</code>, the platform data dir (<code>$XDG_DATA_HOME/sepia/drivers</code> or <code>~/.local/share/sepia/drivers</code>), <code>/usr/local/lib/sepia/drivers</code>, then PATH. The session plane never links a driver — a crashed or hung adapter kills a subprocess, not your daemon. Adding an agent is dropping a binary in a discovery dir; see <a href="./../how-to/write-a-driver.html">write a driver</a>.</p><h2 id="crates" tabindex="-1">Crates <a class="header-anchor" href="#crates" aria-label="Permalink to &quot;Crates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>sepia-core</code></td><td>domain</td><td>Sepia session IR and domain ports — pure domain, zero I/O deps</td></tr><tr><td><code>sepia-proto</code></td><td>domain</td><td>Protocol v2 wire types — REST payloads, SSE events, shared models</td></tr><tr><td><code>sepia-acp</code></td><td>adapter</td><td>ACP client — spawn agents over stdio, typed session ops, tolerant update normalization</td></tr><tr><td><code>sepia-driver</code></td><td>adapter</td><td>SDK for sepia store drivers — manifest, ndjson JSON-RPC serve loop, fs helpers</td></tr><tr><td><code>sepia-driver-claude</code></td><td>adapter</td><td>Claude Code store driver — ~/.claude/projects/*.jsonl transcripts as a SessionRepository over the driver-wire protocol</td></tr><tr><td><code>sepia-driver-cline</code></td><td>adapter</td><td>Cline store driver — ~/.cline/data session dirs as a SessionRepository over the driver-wire protocol</td></tr><tr><td><code>sepia-driver-config</code></td><td>adapter</td><td>tamias-driver-sepia-config — <code>type: sepia-config</code> content driver: agent-config IR packs deployed to agent config dirs.</td></tr><tr><td><code>sepia-driver-cursor</code></td><td>adapter</td><td>Cursor store driver — ~/.cursor chats store.db + agent-transcripts as a SessionRepository over the driver-wire protocol</td></tr><tr><td><code>sepia-driver-devin</code></td><td>adapter</td><td>Devin store driver — sessions.db (sqlite) SessionRepository over the driver-wire protocol</td></tr><tr><td><code>sepia-host</code></td><td>adapter</td><td>Daemon side of the sepia driver protocol — discovery, spawn, registry, remote SessionRepository</td></tr><tr><td><code>sepia-peregrin</code></td><td>adapter</td><td>Sepia&#39;s first-class peregrin adapter — sessions as <code>sepia-session</code> entities over the entity plane</td></tr><tr><td><code>sepia-telemetry</code></td><td>adapter</td><td>Opt-in OpenTelemetry layer over the tracing stack — OTLP export, W3C context propagation</td></tr><tr><td><code>sepia-convert</code></td><td>service</td><td>Cross-store session conversion — history→IR rebuild, Devin-store import with cog grafting</td></tr><tr><td><code>sepia-meta</code></td><td>service</td><td>Sepia-owned per-session overlay metadata (title/pin/projectIds/spans) — a JSON file beside the read-only session stores</td></tr><tr><td><code>sepia-session</code></td><td>service</td><td>Sepia session plane — live-session ownership, lock probes, attach/takeover, prompt/cancel/permission, restore/rewind, and the machine-local composition</td></tr><tr><td><code>sepia-cli</code></td><td>engine</td><td>The sepia engine lib — local store verbs (list/export/import/install/delete), agent config IR ops, driver discovery, and the stdio session-plane service; the <code>sepia</code> command ships as a tamias bins[] shim over this lib</td></tr><tr><td><code>sepia-driver-pavo</code></td><td>driver</td><td>tamias-driver-sepia — pavo view driver over <code>sepia serve</code> (read-only session/agent surfaces) plus engine ops dispatching to the sepia-cli lib</td></tr><tr><td><code>sepia-testkit</code></td><td>testkit</td><td>Sepia test backbone — conformance suites, golden fixtures, mock drivers/agents</td></tr><tr><td><code>xtask</code></td><td>tooling</td><td>sepia-xtask — workspace automation: check / test / coverage / pack / install / fmt.</td></tr></tbody></table><h2 id="distribution-the-tamias-pack" tabindex="-1">Distribution: the tamias pack <a class="header-anchor" href="#distribution-the-tamias-pack" aria-label="Permalink to &quot;Distribution: the tamias pack&quot;">​</a></h2><p>There is no hand-rolled <code>sepia</code> binary. The command ships as the tamias pack in <code>libraries/sepia/</code> — <code>tamias.yaml</code> declares <code>bins: [{name: sepia, shim: cli, driver: sepia}]</code>, so <code>tamias install 9aia:sepia@&lt;ver&gt;</code> (or <code>./libraries/sepia</code> from a checkout) deploys a generated shim that execs <code>tamias-driver-sepia cli &lt;argv&gt;</code> → <code>sepia_cli::run_from</code> in-process. Full argv parity, <code>sepia serve</code> included — the unbounded wire loop rides the same shim as a <em>surface</em>, never an op.</p><p><code>tamias-driver-sepia</code> (the <code>sepia-driver-pavo</code> crate) is also the generated-surface driver: its <code>ops</code> manifest derives from <code>sepia_cli::command()</code> — every bounded verb becomes a <code>cli.&lt;verb&gt;</code> wire query (18 ops today), <code>run &lt;argv&gt;</code> re-execs the engine, and a feature-gated <code>mcp</code> renders the same manifest as MCP tools. The pavo views proxy <code>sepia serve</code> read-only on top of that. See <a href="./../reference/cli.html#the-driver-ops-surface">CLI and environment</a>.</p><h2 id="the-service-wire" tabindex="-1">The service wire <a class="header-anchor" href="#the-service-wire" aria-label="Permalink to &quot;The service wire&quot;">​</a></h2><p><code>sepia serve</code> is the embedding contract. <code>manifest</code> negotiates protocol versions; <code>sessions.*</code>, <code>agents.*</code>, <code>config.*</code>, and the two <code>*.subscribe</code> feeds cover the plane&#39;s surface; <code>session.event</code> and <code>node.event</code> notifications stream live events. The full method table lives in <a href="./../reference/serve-wire.html">serve-wire</a> and <code>crates/sepia-cli/src/serve.rs</code>.</p>`,16)])])}const m=t(o,[["render",i]]);export{v as __pageData,m as default};
